  <script>
    // ─── POSTS DATA (for filtering) ───
    const posts = Array.from(document.querySelectorAll('#news-grid .post-card'));

    // ─── STATE ───
    let currentCategory = 'all';
    let currentSearch = '';

    // ─── DROPDOWN / MEGA MENU ───
    function toggleMenu(itemId) {
      const item = document.getElementById(itemId);
      const isOpen = item.classList.contains('open');
      closeAllMenus();
      if (!isOpen) {
        item.classList.add('open');
        const btn = item.querySelector('button.nav-link');
        if (btn) btn.setAttribute('aria-expanded', 'true');
        document.getElementById('nav-overlay').classList.add('visible');
      }
    }

    function closeAllMenus() {
      document.querySelectorAll('.nav-item.open').forEach(item => {
        item.classList.remove('open');
        const btn = item.querySelector('button.nav-link');
        if (btn) btn.setAttribute('aria-expanded', 'false');
      });
      document.getElementById('nav-overlay').classList.remove('visible');
    }

    // Close on Escape
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') closeAllMenus();
    });

    // ─── CATEGORY FILTER ───
    function filterPosts(category, btn) {
      currentCategory = category;

      // Update pill states
      document.querySelectorAll('.pill').forEach(p => {
        p.classList.remove('active');
        p.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');

      applyFilters();
    }

    // ─── SEARCH ───
    function handleSearch(query) {
      currentSearch = query.toLowerCase().trim();
      applyFilters();
    }

    // ─── COMBINED FILTER LOGIC ───
    function applyFilters() {
      const allPostCards = document.querySelectorAll('.post-card[data-category]');
      let visibleCount = 0;

      allPostCards.forEach(card => {
        const matchesCategory = currentCategory === 'all' || card.dataset.category === currentCategory;
        const searchText = (card.dataset.search || '').toLowerCase();
        const matchesSearch = currentSearch === '' || searchText.includes(currentSearch);

        if (matchesCategory && matchesSearch) {
          card.style.display = '';
          card.removeAttribute('aria-hidden');
          visibleCount++;
        } else {
          card.style.display = 'none';
          card.setAttribute('aria-hidden', 'true');
        }
      });

      // No results state
      const noResults = document.getElementById('no-results');
      if (visibleCount === 0) {
        noResults.classList.add('visible');
      } else {
        noResults.classList.remove('visible');
      }
    }

    // ─── SHOW MORE POSTS ───
    function showMorePosts() {
      const additionalPosts = document.getElementById('additional-posts');
      const showMoreBtn = document.getElementById('show-more-btn');

      additionalPosts.classList.remove('hidden');
      additionalPosts.removeAttribute('aria-hidden');

      // Animate new cards in
      const newCards = additionalPosts.querySelectorAll('.post-card');
      newCards.forEach((card, i) => {
        const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (!prefersReduced) {
          card.style.opacity = '0';
          card.style.transform = 'translateY(12px)';
          setTimeout(() => {
            card.style.transition = 'opacity 220ms ease, transform 220ms ease';
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
          }, i * 60);
        }
      });

      // Re-apply current filters to new cards
      applyFilters();

      // Hide button
      showMoreBtn.classList.add('hidden');
      showMoreBtn.setAttribute('aria-disabled', 'true');

      // Focus first new card for accessibility
      if (newCards.length > 0) {
        setTimeout(() => newCards[0].focus(), 100);
      }
    }
  </script>
